<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import MapaInteractivo from '#lib/components/MapaInteractivo.svelte';

  type Department = { name: string; capital: string; center: [number, number] };
  type Listing = { id: string; title: string; category: string; department: string; quantity: string; price: number; image?: string; description: string };
  type Purchase = { id: string; title: string; department: string; price: number; status: number; created: string };
  const departments: Department[] = [
    {name:'Amazonas',capital:'Chachapoyas',center:[-6.23,-77.87]},{name:'Áncash',capital:'Huaraz',center:[-9.53,-77.53]},{name:'Apurímac',capital:'Abancay',center:[-13.64,-72.88]},{name:'Arequipa',capital:'Arequipa',center:[-16.4,-71.54]},{name:'Ayacucho',capital:'Ayacucho',center:[-13.16,-74.22]},{name:'Cajamarca',capital:'Cajamarca',center:[-7.16,-78.51]},{name:'Callao',capital:'Callao',center:[-12.06,-77.14]},{name:'Cusco',capital:'Cusco',center:[-13.52,-71.97]},{name:'Huancavelica',capital:'Huancavelica',center:[-12.79,-74.97]},{name:'Huánuco',capital:'Huánuco',center:[-9.93,-76.24]},{name:'Ica',capital:'Ica',center:[-14.07,-75.73]},{name:'Junín',capital:'Huancayo',center:[-12.07,-75.21]},{name:'La Libertad',capital:'Trujillo',center:[-8.11,-79.03]},{name:'Lambayeque',capital:'Chiclayo',center:[-6.77,-79.84]},{name:'Lima',capital:'Lima',center:[-12.05,-77.04]},{name:'Loreto',capital:'Iquitos',center:[-3.75,-73.25]},{name:'Madre de Dios',capital:'Puerto Maldonado',center:[-12.59,-69.19]},{name:'Moquegua',capital:'Moquegua',center:[-17.2,-70.93]},{name:'Pasco',capital:'Cerro de Pasco',center:[-10.68,-76.26]},{name:'Piura',capital:'Piura',center:[-5.19,-80.63]},{name:'Puno',capital:'Puno',center:[-15.84,-70.02]},{name:'San Martín',capital:'Moyobamba',center:[-6.03,-76.97]},{name:'Tacna',capital:'Tacna',center:[-18.01,-70.25]},{name:'Tumbes',capital:'Tumbes',center:[-3.57,-80.45]},{name:'Ucayali',capital:'Pucallpa',center:[-8.38,-74.53]}
  ];
  const sections = [
    {id:'inicio',label:'Inicio',icon:'⌂',help:'Explora la compra y venta de ganado, cortes y productos para la cadena ganadera.'},
    {id:'ganado',label:'Ganado',icon:'♧',help:'Filtra lotes por tipo de producto y revisa su precio estimado y departamento.'},
    {id:'subastas',label:'Subastas en vivo',icon:'⚒',help:'Participa en una subasta de prueba. Las ofertas no se envían al servidor.'},
    {id:'ubicacion',label:'Ubicación',icon:'⌖',help:'Elige un departamento para consultar una zona aproximada de los lotes.'},
    {id:'publicar',label:'Subir mi ganado',icon:'＋',help:'Completa el formulario y agrega fotos para ensayar una publicación local.'},
    {id:'compras',label:'Mis compras',icon:'▣',help:'Consulta compras de demostración y observa el avance simulado del traslado.'}
  ];
  const categories = ['Todos','Ganado en pie','Cortes de carne','Carne en canal','Ovinos y caprinos','Insumos y equipos'];
  const seedListings: Listing[] = [
    {id:'L-101',title:'Lote de vacunos para engorde',category:'Ganado en pie',department:'Cajamarca',quantity:'12 cabezas',price:18500,description:'Lote referencial de ganado vacuno; precio total estimado.'},
    {id:'L-102',title:'Novillos criollos',category:'Ganado en pie',department:'Junín',quantity:'8 cabezas',price:14400,description:'Ejemplo de lote para compra y coordinación de traslado.'},
    {id:'L-103',title:'Cortes de res por mayor',category:'Cortes de carne',department:'Lima',quantity:'120 kg',price:3240,description:'Precio de muestra para visualizar una oferta mayorista.'},
    {id:'L-104',title:'Carne de alpaca',category:'Cortes de carne',department:'Puno',quantity:'60 kg',price:2100,description:'Publicación de ejemplo para cortes y productos cárnicos.'},
    {id:'L-105',title:'Canal ovina',category:'Carne en canal',department:'Ayacucho',quantity:'18 canales',price:3960,description:'Oferta de demostración, pendiente de disponibilidad real.'},
    {id:'L-106',title:'Lote de ovinos',category:'Ovinos y caprinos',department:'Huancavelica',quantity:'25 cabezas',price:7500,description:'Lote de ejemplo para explorar categorías ganaderas.'},
    {id:'L-107',title:'Alimento balanceado',category:'Insumos y equipos',department:'La Libertad',quantity:'40 sacos',price:2800,description:'Producto de muestra dentro de insumos ganaderos.'}
  ];
  const auctionSeed = [{id:'S-01',name:'Subasta de novillos',department:'Cajamarca',lot:'10 animales · lote referencial',bid:16200,ends:75},{id:'S-02',name:'Subasta de ovinos',department:'Ayacucho',lot:'20 animales · lote referencial',bid:5900,ends:110}];
  const storageKey='ganadito-demo-mvp-v1';
  let active = $state('inicio');
  let category = $state('Todos');
  let department = $state('');
  let listings = $state<Listing[]>([...seedListings]);
  let purchases = $state<Purchase[]>([]);
  let auctions = $state(auctionSeed.map(x=>({...x})));
  let notice = $state('');
  let origin = $state<[number,number] | null>(null);
  let formTitle = $state(''); let formCategory = $state('Ganado en pie'); let formDepartment = $state(''); let formQuantity = $state(''); let formPrice = $state(''); let formDescription = $state('');
  let photoFiles = $state<File[]>([]); let photoUrls = $state<string[]>([]); let retainedPhotoUrls: string[] = []; let timer: ReturnType<typeof setInterval> | undefined;
  const currentSection = $derived(sections.find(s=>s.id===active)!);
  const shownListings = $derived(listings.filter(l=>(category==='Todos'||l.category===category)&&(!department||l.department===department)));
  const selectedDepartment = $derived(departments.find(d=>d.name===department));
  const selectedLot = $derived(listings.find(l=>l.department===department) ?? listings[0]!);
  const mapMarkers = $derived(selectedDepartment ? [{id:selectedLot.id,nombre_comercial:selectedLot.title,tipo:selectedLot.category,latitud:selectedDepartment.center[0],longitud:selectedDepartment.center[1],direccion_texto:null,distancia_km:origin ? haversine(origin,selectedDepartment.center) : null,ubicacion_aproximada:true}] : []);
  const purchaseSteps=['Solicitud de compra creada (demo)','Preparando el traslado (demo)','En ruta — seguimiento simulado','Entrega de demostración completada'];
  onMount(()=>{
    try { const saved=localStorage.getItem(storageKey); if(saved){const data=JSON.parse(saved); if(Array.isArray(data.purchases)) purchases=data.purchases; if(Array.isArray(data.listings)) listings=[...seedListings,...data.listings];} } catch { /* demo state is optional */ }
    timer=setInterval(()=>{ auctions=auctions.map(a=>({...a,ends:Math.max(0,a.ends-1)})); purchases=purchases.map(p=>({...p,status:Math.min(3,p.status+(Math.random()<.13?1:0))})); saveDemo(); },1000);
  });
  onDestroy(()=>{if(timer)clearInterval(timer); retainedPhotoUrls.forEach(URL.revokeObjectURL); photoUrls.filter(url=>!retainedPhotoUrls.includes(url)).forEach(URL.revokeObjectURL);});
  function haversine(a:[number,number],b:[number,number]){const rad=Math.PI/180, dLat=(b[0]-a[0])*rad,dLon=(b[1]-a[1])*rad,x=Math.sin(dLat/2)**2+Math.cos(a[0]*rad)*Math.cos(b[0]*rad)*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
  function saveDemo(){try{localStorage.setItem(storageKey,JSON.stringify({purchases,listings:listings.filter(l=>l.id.startsWith('D-'))}));}catch{/* storage may be disabled */}}
  function go(id:string){active=id;notice='';window.scrollTo({top:0,behavior:'smooth'});}
  function askLocation(){if(!navigator.geolocation){notice='Este navegador no ofrece geolocalización.';return;} notice='Solicitando ubicación solo para calcular una distancia aproximada…'; navigator.geolocation.getCurrentPosition(p=>{origin=[p.coords.latitude,p.coords.longitude];notice='Ubicación usada solo en este dispositivo para el cálculo. No se guardó ni envió.';},()=>{notice='No se obtuvo tu ubicación. Selecciona un departamento como referencia para calcular la distancia.';},{enableHighAccuracy:false,timeout:10000,maximumAge:300000});}
  function handlePhotos(event:Event){const input=event.currentTarget as HTMLInputElement; const files=Array.from(input.files??[]).filter(f=>f.type.startsWith('image/')).slice(0,5); photoUrls.forEach(URL.revokeObjectURL); photoFiles=files; photoUrls=files.map(f=>URL.createObjectURL(f));}
  function publish(event:SubmitEvent){event.preventDefault();if(!formTitle.trim()||!formDepartment||!formQuantity||!formPrice){notice='Completa título, departamento, cantidad y precio estimado.';return;} const image=photoUrls[0]; retainedPhotoUrls.push(...photoUrls); const item:Listing={id:`D-${Date.now()}`,title:formTitle.trim(),category:formCategory,department:formDepartment,quantity:formQuantity,price:Number(formPrice),image,description:formDescription.trim()||'Publicación de práctica creada en esta sesión.'};listings=[item,...listings];saveDemo();formTitle='';formQuantity='';formPrice='';formDescription='';formDepartment='';photoFiles=[];photoUrls=[];notice='Publicación de demostración agregada. Solo está disponible en este navegador.';go('ganado');}
  function buy(item:Listing){const p:Purchase={id:`DEMO-${Date.now().toString().slice(-6)}`,title:item.title,department:item.department,price:item.price,status:0,created:new Date().toLocaleString('es-PE')};purchases=[p,...purchases];saveDemo();notice='Compra simulada creada. No se realizó pago ni se generó una orden real.';go('compras');}
  function bid(id:string){auctions=auctions.map(a=>a.id===id?{...a,bid:a.bid+100}:a);notice='Puja local de demostración registrada en pantalla. No se envió al servidor ni es una oferta real.';}
</script>

<svelte:head><title>Demo MVP Ganadito | Simulación</title><meta name="description" content="Demostración local del marketplace ganadero de Ganadito." /></svelte:head>
